selector_to_html = {"a[href=\"#pyskyfire.turbine.duty.TurbineDuty.from_stations\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty.from_stations\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_stations</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_in</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_out</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Two network stations, by their pressures and the inlet\u2019s T and mdot.</p><p>Network stations are total states, so the outlet basis is total. The\noutlet station\u2019s temperature is not read: it is what the real\nturbine\u2019s losses made of the flow.</p></dd>", "a[href=\"#pyskyfire.turbine.duty.TurbineDuty.__post_init__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty.__post_init__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__post_init__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.turbine.duty.TurbineDuty\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.duty.</span></span><span class=\"sig-name descname\"><span class=\"pre\">TurbineDuty</span></span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../../thermo/duty/MachineDuty.html#pyskyfire.thermo.duty.MachineDuty\" title=\"pyskyfire.thermo.duty.MachineDuty\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.thermo.duty.MachineDuty</span></code></a></p><p>What a turbine is asked to do. See <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">MachineDuty</span></code>.</p><p>Build one with <a class=\"reference internal\" href=\"#pyskyfire.turbine.duty.TurbineDuty.from_states\" title=\"pyskyfire.turbine.duty.TurbineDuty.from_states\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_states()</span></code></a> or <a class=\"reference internal\" href=\"#pyskyfire.turbine.duty.TurbineDuty.from_stations\" title=\"pyskyfire.turbine.duty.TurbineDuty.from_stations\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_stations()</span></code></a>.</p></dd>", "a[href=\"#pyskyfire.turbine.duty.TurbineDuty.specific_diameter\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty.specific_diameter\">\n<span class=\"sig-name descname\"><span class=\"pre\">specific_diameter</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">diameter</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>Dimensionless <code class=\"docutils literal notranslate\"><span class=\"pre\">Ds</span> <span class=\"pre\">=</span> <span class=\"pre\">D*\u0394h_s**0.25/sqrt(Q_out)</span></code> for a rotor of <code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span></code> [m].</p></dd>", "a[href=\"#pyskyfire.turbine.duty.TurbineDuty.specific_speed\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty.specific_speed\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">specific_speed</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Dimensionless <code class=\"docutils literal notranslate\"><span class=\"pre\">Ns</span> <span class=\"pre\">=</span> <span class=\"pre\">omega*sqrt(Q_out)/\u0394h_s**0.75</span></code>.</p><p>The flow is taken at the isentropic outlet, the convention of Balje\u2019s\ncharts and of turboflow.</p></dd>", "a[href=\"#pyskyfire.turbine.duty.TurbineDuty.pressure_ratio\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty.pressure_ratio\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">pressure_ratio</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Inlet total pressure over outlet pressure.</p></dd>", "a[href=\"#pyskyfire.turbine.duty.TurbineDuty.blade_speed\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty.blade_speed\">\n<span class=\"sig-name descname\"><span class=\"pre\">blade_speed</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">diameter</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>Blade speed [m s\u207b\u00b9] at <code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span></code> [m].</p></dd>", "a[href=\"#pyskyfire.turbine.duty.TurbineDuty.from_states\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty.from_states\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_states</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mdot</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p0_in</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T0_in</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_out</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outlet_basis</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'total'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A medium, a mass flow, the inlet total state and the outlet pressure.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fluid</span></code> is a CoolProp name, a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Fluid</span></code>, or\nany <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">EquationOfState</span></code>.</p></dd>", "a[href=\"#pyskyfire.turbine.duty.TurbineDuty.spouting_velocity\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty.spouting_velocity\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">spouting_velocity</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p><code class=\"docutils literal notranslate\"><span class=\"pre\">c0</span> <span class=\"pre\">=</span> <span class=\"pre\">sqrt(2*\u0394h_s)</span></code> [m s\u207b\u00b9], the speed the whole head would make.</p></dd>", "a[href=\"#pyskyfire.turbine.duty.TurbineDuty.blade_jet_ratio\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.duty.TurbineDuty.blade_jet_ratio\">\n<span class=\"sig-name descname\"><span class=\"pre\">blade_jet_ratio</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">diameter</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p><code class=\"docutils literal notranslate\"><span class=\"pre\">u/c0</span></code> at <code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span></code> [m].</p></dd>", "a[href=\"#pyskyfire-turbine-duty-turbineduty\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.turbine.duty.TurbineDuty<a class=\"headerlink\" href=\"#pyskyfire-turbine-duty-turbineduty\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"../../thermo/duty/MachineDuty.html#pyskyfire.thermo.duty.MachineDuty\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.duty.MachineDuty\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.duty.</span></span><span class=\"sig-name descname\"><span class=\"pre\">MachineDuty</span></span></dt><dd><p>Head, flow and speed asked of one turbomachine.</p><p>Build one through a subclass\u2019s constructors rather than field by field;\nthey are what keep the fields consistent with one another.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
